 def json_response_documentation(
     description: str,
     example: Any,
 ) -> dict[str, Any]:
     return {
         "description": description,
         "content": {
             "application/json": {
                 "examples": {
                     "success": {
                         "summary": "Successful response",
                         "value": example,
                     }
                 }
             }
         },
     }


 def json_error_example(
     description: str,
     message: str,
     code: str = "HTTP_ERROR",
 ) -> dict[str, Any]:
     return {
         "description": description,
         "content": {
             "application/json": {
                 "examples": {
                     "error": {
                         "summary": description,
                         "value": {
                             **ERROR,
                             "error": {"code": code, "message": message},
                         },
                     }
                 }
             }
         },
     }

